        count = low;
    }
    auto plan     = std::make_shared<Demotion>();
    plan->owner   = &session;
    plan->records = group.sources;
    for (std::size_t i = 0; i < count; ++i) {
        const auto& candidate = candidates[i];
        if (candidate.image.valid())
